package net.officefloor.hq.app;

import net.officefloor.server.http.HttpException;
import net.officefloor.server.http.HttpStatus;
import net.officefloor.web.HttpQueryParameter;
import net.officefloor.web.ObjectResponse;

/**
 * GET /api/invoices/get?id=&lt;id&gt; — fetch a single invoice by id, so a view showing one invoice
 * (e.g. the invoice detail) can read its derived status (SENT/PARTIAL/PAID) after recording a
 * payment, without re-listing the whole project.
 */
public class InvoiceGetLogic {

    public void service(@HttpQueryParameter("id") String id, InvoiceRepository repository,
            ObjectResponse<Invoice> response) {
        long invoiceId = id == null || id.isBlank() ? 0 : Long.parseLong(id.trim());
        Invoice invoice = repository.findById(invoiceId);
        if (invoice == null) {
            throw new HttpException(HttpStatus.NOT_FOUND, "No such invoice.");
        }
        response.send(invoice);
    }
}

package net.officefloor.hq.app;

import java.math.BigDecimal;

/**
 * An invoice billed on a project. Serialised as JSON by the /api/invoices routes; belongs to
 * exactly one project (projectId). Carries a payment status (UNPAID by default, PAID once settled)
 * and two dates: issuedDate (when it went out) and dueDate (when it is due), as ISO yyyy-MM-dd.
 * {@code due} is how much is still owed: the invoice amount minus everything paid against it.
 * {@code discountPct} is a percentage (0..100) taken off the subtotal; the front-end shows the
 * subtotal, the discount and the final total (subtotal minus the discount).
 */
public record Invoice(long id, long projectId, BigDecimal amount, String status, String issuedDate,
        String dueDate, BigDecimal due, BigDecimal discountPct) {
}

